reference_solution:
def next_reusable_time(time):
    allowed = set(time.replace(':', ''))
    hour, minute = map(int, time.split(':'))
    current = hour * 60 + minute
    while True:
        current = (current + 1) % (24 * 60)
        candidate = f'{current // 60:02d}:{current % 60:02d}'
        if set(candidate.replace(':', '')) <= allowed:
            return candidate

